package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's audit lines as the file holds them, newest first; with a name, only the lines about that person (a
 *  name= or person= field holding it, case and surrounding spaces ignored), followed by the lines about them on each
 *  of the sheet's descendants (by id, each newest first), then, when the person of that name
 *  (or alias) on this sheet was transferred here, by the lines about them on the sheet they came from, newest first.
 *  Reads the file; keeps no copy. */
public class RespondWithAuditLines {
    public void respond(@PathVariable("sheetId") String sheetId, @RequestParam(name = "name", required = false) String name,
            Audit audit, PersonRepository people, SheetRepository sheets, ObjectResponse<List<String>> response) {
        String sheet = sheetId.trim();
        String key = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
        List<String> all = audit.lines();
        List<String> lines = about(all, sheet, key);
        if (!key.isEmpty()) {
            for (String descendant : sheets.descendants(sheet)) {
                lines.addAll(about(all, descendant, key));
            }
            Person person = people.findByName(sheet, key);
            if (person != null && person.origin() != null) {
                lines.addAll(about(all, person.origin(), person.name().trim().toLowerCase(Locale.ROOT)));
            }
        }
        response.send(lines);
    }

    /** The sheet's lines (about the person of the key, unless blank), newest first. */
    private static List<String> about(List<String> all, String sheet, String key) {
        List<String> lines = new ArrayList<>();
        for (String line : all) {
            if (onSheet(line, sheet) && (key.isEmpty() || about(line, key))) {
                lines.add(line);
            }
        }
        Collections.reverse(lines);
        return lines;
    }

    /** Whether the line's sheet= field is the sheet. */
    private static boolean onSheet(String line, String sheet) {
        for (String field : line.split(" ")) {
            if (field.startsWith("sheet=")) {
                return field.substring("sheet=".length()).equals(sheet);
            }
        }
        return false;
    }

    /** Whether a name= or person= field of the line holds the name (already in comparison form). */
    private static boolean about(String line, String key) {
        String lower = line.toLowerCase(Locale.ROOT);
        for (String label : new String[] { " name=", " person=" }) {
            int at = lower.indexOf(label);
            while (at >= 0) {
                String rest = lower.substring(at + label.length());
                if (rest.startsWith(key) && (rest.length() == key.length() || rest.charAt(key.length()) == ' ')) {
                    return true;
                }
                at = lower.indexOf(label, at + 1);
            }
        }
        return false;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.delegation.DelegationRepository;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    private final DelegationRepository delegations;

    /** The records held back on this thread while a change that may yet be refused is made (null: none held). */
    private final ThreadLocal<List<String>> held = new ThreadLocal<>();

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, DelegationRepository delegations) {
        this.file = Path.of(path);
        this.delegations = delegations;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user acting as a
     *  steward by delegation (in force by the sheet's today) ends with for=<the steward who delegated>; the ROLLUP
     *  and TOTALS lines do not. */
    public synchronized void record(String entry) {
        entry = entry + delegatedFor(entry);
        List<String> holding = held.get();
        if (holding != null) {
            holding.add(entry);
            return;
        }
        write(entry);
    }

    /** Hold back this thread's records from now on until {@link #release()} writes them or {@link #drop()} discards
     *  them, so a change refused part way through writes no audit line. */
    public void hold() {
        held.set(new ArrayList<>());
    }

    /** Write the records held back, in the order they were made, and stop holding. */
    public synchronized void release() {
        List<String> holding = held.get();
        held.remove();
        if (holding != null) {
            holding.forEach(this::write);
        }
    }

    /** Discard any records still held back, and stop holding. */
    public void drop() {
        held.remove();
    }

    private synchronized void write(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** " for=<steward>" when the record's user (by=) acts by a delegation in force on its sheet (sheet=), else "". */
    private String delegatedFor(String entry) {
        String[] fields = entry.split(" ");
        if (fields[0].equals("ROLLUP") || fields[0].equals("TOTALS")) {
            return "";
        }
        String sheet = null;
        String by = null;
        for (String field : fields) {
            if (sheet == null && field.startsWith("sheet=")) {
                sheet = field.substring("sheet=".length());
            } else if (by == null && field.startsWith("by=")) {
                by = field.substring("by=".length());
            }
        }
        if (sheet == null || by == null) {
            return "";
        }
        String steward = delegations.delegator(sheet, by);
        return steward == null ? "" : " for=" + steward;
    }

    /** Every record the file holds now, in file order (none when there is no file). */
    public synchronized List<String> lines() {
        try {
            if (!Files.exists(file)) {
                return List.of();
            }
            return Files.readAllLines(file, StandardCharsets.UTF_8).stream().filter(l -> !l.isEmpty()).toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheet';

/** The audit viewer: the sheet's audit lines exactly as the audit file holds them, newest first. A name in the
 *  filter shows only the lines about that person (name= or person= that name, compared as names are). Each press
 *  of Show re-reads the file. */
function AuditViewer({ sheetId }: { sheetId: string; user: string }) {
  const [filter, setFilter] = useState('');
  const [shown, setShown] = useState<{ name: string; n: number } | null>(null);
  const lines = useQuery({
    queryKey: ['sheet', sheetId, 'audit', shown?.name ?? '', shown?.n ?? 0],
    queryFn: () =>
      getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/audit?name=${encodeURIComponent(shown!.name)}`),
    enabled: shown !== null,
  });

  return (
    <section>
      <h2>Audit</h2>
      <input
        data-testid="audit-filter"
        placeholder="Name (blank for all)"
        value={filter}
        onChange={(e) => setFilter(e.target.value)}
      />{' '}
      <button
        type="button"
        data-testid="audit-show"
        onClick={() => setShown((s) => ({ name: filter.trim(), n: (s?.n ?? 0) + 1 }))}
      >
        Show
      </button>
      {shown && lines.data && (
        <ol>
          {lines.data.map((line, i) => (
            <li key={i} data-testid="audit-line">
              {line}
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 90, Component: AuditViewer });
